    case Tag::kApproved:
      return mojo::Equals(*(data_.approved), *(other.data_.approved));
    case Tag::kError:
      return mojo::Equals(*(data_.error), *(other.data_.error));
    case Tag::kCanceled:
      return mojo::Equals(*(data_.canceled), *(other.data_.canceled));
    case Tag::kDeclined:
      return mojo::Equals(*(data_.declined), *(other.data_.declined));
